const icon = {Dashboard:lucideIcon('layoutDashboard'),Programmes:lucideIcon('bookOpen'),Participants:lucideIcon('usersRound'),Attendance:lucideIcon('calendarCheck'),'Live Class':lucideIcon('video'),'Follow-Up':lucideIcon('heartHandshake'),'Staff Inbox':lucideIcon('inbox'),Messages:lucideIcon('messagesSquare'),Reports:lucideIcon('chartNoAxesColumnIncreasing'),Settings:lucideIcon('settings'),Home:lucideIcon('house'),Discover:lucideIcon('compass'),'My Programmes':lucideIcon('bookOpen'),Profile:lucideIcon('userRound')};
function toast(message) { const old=$('.toast'); if(old)old.remove(); const el=document.createElement('div'); el.className='toast';el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),2800); }
async function api(path, options={}){const headers={...(options.body?{'Content-Type':'application/json'}:{}),...(authToken?{Authorization:`Bearer ${authToken}`}:{})};const response=await fetch(path,{...options,headers:{...headers,...options.headers}});if(!response.ok){let message='Something went wrong. Please try again.';try{message=(await response.json()).detail||message;}catch{}throw new Error(message);}return response.json();}
function loginPage(){return `<div class="login-shell"><div class="login-card"><a class="brand"><span class="brandmark">v</span> voxera</a><div class="eyebrow" style="margin-top:36px">A BETTER WAY TO REACH EVERYONE</div><h1 class="page-title" style="font-size:31px">Welcome to Voxera</h1><p class="page-subtitle">Sign in to your local demo workspace.</p><div class="login-choices"><button class="login-choice" onclick="loginDemo('organiser')"><span class="mini-avatar">EO</span><span><b>Continue as organiser</b><small>Manage programmes and participants</small></span><span>→</span></button><button class="login-choice" onclick="loginDemo('participant')"><span class="mini-avatar">AO</span><span><b>Continue as participant</b><small>Explore and attend programmes</small></span><span>→</span></button></div><div class="login-divider">or use demo account details</div><form onsubmit="loginForm(event)"><div class="field"><label>Email</label><input id="login-email" type="email" required value="organiser@voxera.local"></div><div class="field"><label>Password</label><input id="login-password" type="password" required value="demo123"></div><button class="btn btn-primary" style="width:100%">Sign in</button></form><div class="row-meta" style="text-align:center;margin-top:14px">Demo passwords are shown in README.md · Data stays on this device</div></div></div>`;}
async function loginForm(event){event.preventDefault();try{const result=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('#login-email').value,password:$('#login-password').value})}).then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.detail);return d;});authToken=result.token;currentUser=result.user;localStorage.setItem('voxera-token',authToken);role=currentUser.role;localStorage.setItem('voxera-role',role);page=role==='participant'?'Home':'Dashboard';await hydrate();render();}catch(error){toast(error.message||'Sign-in failed.');}}
async function loginDemo(value){const accounts={organiser:'organiser@voxera.local',participant:'amara@voxera.local',admin:'admin@voxera.local'};const username=accounts[value]||accounts.organiser;try{const result=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username,password:'demo123'})}).then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.detail);return d;});authToken=result.token;currentUser=result.user;role=value;localStorage.setItem('voxera-token',authToken);localStorage.setItem('voxera-role',role);page=role==='participant'?'Home':'Dashboard';await hydrate();render();}catch(error){toast(error.message||'Could not sign in.');}}
function setRole(value){loginDemo(value);}
function logout(){authToken='';currentUser=null;conversationId=null;state.accountProfile=null;state.settings=null;localStorage.removeItem('voxera-token');document.documentElement.dataset.theme='light';render();}
async function hydrate(){try{const [programmes,people,enrolments,cases,conversations,profile,certificates]=await Promise.all([api('/api/programmes'),role==='participant'?Promise.resolve([]):api('/api/participants'),api('/api/enrolments'),role==='participant'?Promise.resolve([]):api('/api/cases'),api('/api/conversations'),role==='participant'?api('/api/profile'):Promise.resolve(null),role==='participant'?api('/api/certificates'):Promise.resolve([])]);state.programmes=programmes.map((p,i)=>({id:p.id,title:p.title,category:p.category,format:p.format,location:p.location,dates:`${p.start_date} — ${p.end_date}`,spots:Math.max(0,p.capacity-p.enrolled_count),status:p.status[0].toUpperCase()+p.status.slice(1),art:['⌘','✳','↗'][i%3],cover:['c3','','c2'][i%3],desc:p.description}));state.applied=enrolments.filter(e=>e.status==='applied'||e.status==='waitlisted').map(e=>e.programme_id);state.applications=enrolments.filter(e=>e.status==='applied'||e.status==='waitlisted');state.approved=enrolments.some(e=>e.status==='enrolled');state.people=people.map(p=>[p.name,p.language,p.area,`${Math.round(p.attendance)}%`,p.risk,p.name.split(' ').map(x=>x[0]).join('').slice(0,2),p.id]);state.cases=cases.map(c=>({id:c.id,status:c.status,name:c.participant_name,initials:c.participant_name.split(' ').map(x=>x[0]).join(''),urgency:c.urgency,category:c.category,message:c.original_text,translation:c.translation_en,summary:c.summary,reply:c.suggested_reply}));state.casesDone=state.cases.map((c,i)=>c.status==='escalated'?null:i).filter(i=>i!==null);state.profile=profile;state.certificates=certificates;if(conversations.length){conversationId=conversations[0].id;const messages=await api(`/api/conversations/${conversationId}/messages`);state.messages=messages.map(m=>({id:m.id,text:m.body,ai:!!m.ai,mine:!!m.sender_id&&m.sender_id===currentUser.id,time:new Date(m.created_at).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}));}}catch(error){console.warn('Voxera sync:',error.message);}}
function navItems(){return role==='participant'?['Home','Discover','My Programmes','Messages','Profile']:['Dashboard','Programmes','Participants','Attendance','Live Class','Follow-Up','Staff Inbox','Messages','Reports','Settings'];}
function topbar(){return `<header class="topbar"><a class="brand" href="#" onclick="return false"><span class="brandmark">v</span> voxera</a><div class="top-right"><span class="badge">●&nbsp; Local demo</span><select class="mode-select" aria-label="Switch demo account" onchange="setRole(this.value)"><option value="organiser" ${role==='organiser'?'selected':''}>Organiser view</option><option value="participant" ${role==='participant'?'selected':''}>Participant view</option><option value="admin" ${role==='admin'?'selected':''}>Admin view</option></select><div class="avatar">${currentUser?.name?.split(' ').map(x=>x[0]).join('').slice(0,2)||'VX'}</div><button class="btn btn-outline btn-small" onclick="logout()">Sign out</button></div></header>`;}
function layout(content){if(role==='participant')return `${topbar()}<div class="participant-layout">${content}</div>`;return `${topbar()}<div class="layout"><aside class="sidebar"><div class="side-label">Workspace</div>${navItems().map(n=>`<button class="nav-item ${page===n?'active':''}" onclick="go('${n}')"><span class="nav-icon">${icon[n]}</span>${n}</button>`).join('')}<div class="side-bottom"><button class="nav-item" onclick="openModal('help')"><span class="nav-icon">ⓘ</span>Help centre</button><div class="notice" style="margin:10px 4px 0">Your demo data is saved on this device.</div></div></aside><main class="content">${content}</main></div>`;}
