function stat(label,value,foot,symbol){const statIcon={'▤':'bookOpen','♙':'usersRound','◷':'clock','⚑':'inbox'}[symbol]||'sparkles';return `<div class="card stat"><div class="stat-top"><span>${label}</span><span class="stat-icon">${lucideIcon(statIcon,17)}</span></div><div class="stat-value">${value}</div><div class="stat-foot"><span class="positive">${foot}</span></div></div>`;}
function progRow(p,meta='Online · 6 sessions',badgeText='In progress'){const art=lucideIcon(p.format==='Physical'?'mapPin':p.format==='Hybrid'?'usersRound':'bookOpen',20);return `<div class="programme-row"><div class="programme-art ${p.cover==='c2'?'orange':p.cover==='c3'?'blue':''}">${art}</div><div class="row-main"><div class="row-title">${esc(p.title||'Programme')}</div><div class="row-meta">${meta}</div></div><span class="badge">${badgeText}</span></div>`;}
function sessionRow(day,title,meta){return `<div class="session"><div class="date-tile"><span>OCT</span><b>${day}</b></div><div class="session-info"><div class="session-title">${title}</div><div class="session-meta">${meta}</div></div><span class="badge gray">Upcoming</span></div>`;}
function dashboard(){const enrolled=26+(state.applied.length?state.applied.length:0);return `${head('MONDAY, 05 OCTOBER 2026','Good morning, Efeoluwa 👋','Here’s what’s happening across your programmes today.','<button class="btn btn-primary" onclick="openModal(\'new-programme\')">＋&nbsp; New Programme</button>')}<section class="grid stats">${stat('Active programmes','08','2 starting this month','▤')}${stat('Participants',String(enrolled),'↑ 12% this month','♙')}${stat('Average attendance','76%','↑ 4.2% this month','◷')}${stat('Open escalations',String(Math.max(2,state.cases.length-state.casesDone.length)),'Needs a response','⚑')}</section><section class="grid split"><div class="grid"><article class="card"><div class="card-head"><div class="card-title">Your programmes</div><button class="text-link" onclick="go('Programmes')">View all →</button></div><div class="programme-list">${state.programmes.map(p=>progRow(p,`${p.format} · ${p.spots?`${p.spots} places left`:'Waitlist open'}`,p.status)).join('')}</div></article><article class="card"><div class="card-head"><div><div class="card-title">Attendance over time</div><div class="row-meta" style="margin-top:5px">Average across all active programmes</div></div><span class="badge">Last 6 sessions</span></div><div class="chart">${[46,61,54,77,68,88,73,94].map((v,i)=>`<div class="bar-wrap"><div class="bar ${i===7?'current':''}" style="height:${v}%"></div></div>`).join('')}</div><div class="chart-labels"><span>Session 1</span><span>Session 3</span><span>Session 5</span><span>Session 8</span></div></article></div><div class="grid"><article class="card"><div class="card-head"><div class="card-title">Coming up</div><span class="text-link" onclick="go('Attendance')">Calendar ↗</span></div>${sessionRow('08','Digital Skills · Portfolio clinic','Online · 10:00 AM')}${sessionRow('10','Health Champions · Check-in','Ikeja Centre · 1:30 PM')}${sessionRow('12','Business Ready · Pricing','Hybrid · 11:00 AM')}</article><article class="card"><div class="card-head"><div class="card-title">Needs a little care</div><button class="text-link" onclick="go('Participants')">View participants →</button></div><div class="risk-list">${state.people.filter(p=>p[4]==='At risk').slice(0,4).map(p=>`<div class="risk"><span class="mini-avatar">${p[5]}</span><div class="risk-name">${p[0]}<div class="risk-meta">${p[2]}</div></div><span class="risk-score">${p[3]}</span></div>`).join('')}</div></article></div></section>`;}
function programmeCards(){let items=state.programmes.filter(p=>programmeFilter==='All'||p.category===programmeFilter);return items.length?`<section class="grid programme-cards">${items.map((p,i)=>`<article class="card programme-card"><div class="programme-cover ${p.cover}"><span class="cover-icon">${p.art}</span><span class="cover-tag">${p.category}</span></div><div class="programme-body"><h3>${p.title}</h3><p>${p.desc}</p><div class="row-meta">◷ &nbsp;${p.dates}<br>⌖ &nbsp;${p.location}</div><div class="program-foot"><span class="capacity">${p.status==='Full'?'Waitlist available':p.spots+' spaces remaining'} · ${p.format}</span><button class="btn btn-small ${p.status==='Full'?'btn-soft':'btn-primary'}" onclick="${role==='participant'?`apply(${p.id})`:`editProgramme(${p.id})`}">${role==='participant'?(p.status==='Full'?'Join waitlist':state.applied.includes(p.id)?'Applied':'Explore'):'Manage'}</button></div></div></article>`).join('')}</section>`:'<div class="card empty">No Programmes match those filters. Try a different category.</div>';}
function programmes(){const categories=['All',...new Set(state.programmes.map(p=>p.category))];return `${head(role==='participant'?'FIND YOUR NEXT STEP':'PROGRAMME MANAGEMENT',role==='participant'?'Find a programme that fits':'Programmes','Practical opportunities, built around the people they serve.',role==='organiser'?'<button class="btn btn-primary" onclick="openModal(\'new-programme\')">＋&nbsp; New Programme</button>':'')}<div class="toolbar"><input class="search" id="programme-search" placeholder="⌕  Search programmes" oninput="filterSearch(this.value)"><div class="filters">${categories.map(c=>`<button class="filter ${programmeFilter===c?'active':''}" onclick="setProgrammeFilter('${c}')">${c}</button>`).join('')}</div></div>${programmeCards()}`;}
function participants(){return `${head('YOUR COMMUNITY','Participants','A closer look at who’s learning, showing up and could use a hand.','<button class="btn btn-outline" onclick="downloadCsv()">↓&nbsp; Export CSV</button>')}<div class="toolbar"><input class="search" placeholder="⌕  Search by name or programme" oninput="searchPeople(this.value)"><div class="filters"><button class="filter active">All participants · ${state.people.length+20}</button><button class="filter">At risk · 8</button><button class="filter">On track · 18</button></div></div><div class="card table-card"><table class="table" id="people-table"><thead><tr><th>Participant</th><th>Language</th><th>Programme</th><th>Attendance</th><th>Status</th><th>Last contact</th></tr></thead><tbody>${state.people.map(p=>`<tr><td><div class="person-cell"><span class="mini-avatar">${p[5]}</span>${p[0]}</div></td><td class="muted">${p[1]}</td><td>${p[2]}</td><td><b>${p[3]}</b></td><td><span class="badge ${p[4]==='At risk'?'orange':''}">${p[4]}</span></td><td class="muted">${['Today','Yesterday','2 days ago'][Math.floor(Math.random()*3)]}</td></tr>`).join('')}</tbody></table></div>`;}
function attendance(){const names=state.people.slice(0,6);return `${head('SHOWING UP','Attendance','Every session tells a story. Here’s how this cohort is doing.','<button class="btn btn-outline" onclick="downloadCsv()">↓&nbsp; Export CSV</button>')}<div class="toolbar filters-panel"><select class="select"><option>Digital Skills for Work</option><option>Community Health Champions</option><option>Small Business Ready</option></select><select class="select"><option>All sessions</option><option>Session 1 · Getting started</option><option>Session 2 · Digital confidence</option><option>Session 3 · Portfolio clinic</option></select><button class="btn btn-primary btn-small" onclick="openModal('qr')">▦&nbsp; QR check-in</button><button class="btn btn-soft btn-small" onclick="markAttendance()">＋&nbsp; Mark present</button></div><section class="grid stats">${stat('Session attendance','78%','↑ 6% from last session','◷')}${stat('Present today','19 / 24','4 joining online','✓')}${stat('Recording pending','3','Deadline in 2 days','▷')}${stat('Certificate track','17','On pace to complete','✧')}</section><div class="card table-card"><table class="table"><thead><tr><th>Participant</th><th>Session 1</th><th>Session 2</th><th>Session 3</th><th>Session 4</th><th>Overall</th></tr></thead><tbody>${names.map((p,i)=>`<tr><td><div class="person-cell"><span class="mini-avatar">${p[5]}</span>${p[0]}</div></td>${[0,1,2,3].map(j=>`<td><span class="attendance-symbol ${((i+j*2)%7===1)?'missed':((i+j)%8===4?'pending':'')}">${((i+j*2)%7===1)?'×':((i+j)%8===4?'◷':'✓')}</span></td>`).join('')}<td><b>${p[3]}</b></td></tr>`).join('')}</tbody></table></div>`;}
function liveClass(){return `${head('TOGETHER, IN REAL TIME','Live class','Go live from your laptop. Participants can join from any phone on your Wi‑Fi.')}<section class="grid split"><div class="card"><div class="card-head"><div class="card-title">Session setup</div><span class="badge ${state.live?'red':''}">${state.live?'LIVE NOW':'Ready'}</span></div><div class="field"><label>Programme</label><select class="select"><option>Digital Skills for Work</option><option>Community Health Champions</option></select></div><div class="field"><label>Session</label><select class="select"><option>Session 3 · Portfolio clinic</option><option>Session 4 · Show and tell</option></select></div><div class="field"><label>Session duration</label><select class="select"><option>60 minutes</option><option>90 minutes</option></select></div><div class="notice">Your camera and microphone stay on this device. In this demo, presence can be simulated to rehearse the participant flow.</div><button class="btn ${state.live?'btn-soft':'btn-primary'}" onclick="toggleLive()">${state.live?'■  End session':'▶  Start live session'}</button></div><div class="card"><div class="live-stage"><div class="live-pulse">${state.live?'●  LIVE':'◉  SESSION PREVIEW'}</div><div class="live-center"><button class="play" onclick="toggleLive()">${state.live?'Ⅱ':'▶'}</button><h3>${state.live?'You’re live with your group':'Ready when you are'}</h3><p>${state.live?'12 participants connected':'Your live room will appear here'}</p><div class="wave">${Array.from({length:22},(_,i)=>`<i style="height:${7+(i*13)%28}px"></i>`).join('')}</div></div></div></div></section><article class="card" style="margin-top:16px"><div class="card-head"><div class="card-title">Here with you <span class="badge" style="margin-left:6px">${state.live?'12':'0'} participants</span></div><span class="row-meta">Presence updates while the session is live</span></div><div class="programme-list">${state.people.slice(0,4).map(p=>`<div class="risk"><span class="mini-avatar">${p[5]}</span><div class="risk-name">${p[0]}<div class="risk-meta">Joined ${state.live?'10:02 AM':'Not joined yet'}</div></div><div class="progress" style="width:100px"><i style="width:${state.live?'64':'0'}%"></i></div><span class="badge ${state.live?'':'gray'}">${state.live?'64% present':'Waiting'}</span></div>`).join('')}</div></article>`;}
function followup(){return `${head('CARE THAT KEEPS GOING','Follow-Up','Gentle, timely check-ins help participants stay connected.')}<div class="notice">✦ &nbsp; Voxera AI can handle routine replies. Sensitive topics, uncertainty and requests for a person always go to your team.</div><section class="grid follow-layout"><article class="card"><div class="card-head"><div class="card-title">When should Voxera check in?</div><span class="badge">${state.followup?'Automation on':'Paused'}</span></div>${[['✧','Missed a session','Check in after a participant is marked absent'],['◷','Two sessions in a row','Reach out when someone misses two consecutive sessions'],['▷','Recording deadline','A friendly nudge before their recording expires'],['♧','After the programme','1 week, 1 month and 3 months after completion']].map(x=>`<div class="trigger"><span class="trigger-icon">${x[0]}</span><div class="trigger-copy"><b>${x[1]}</b><p>${x[2]}</p></div><input class="switch" type="checkbox" checked></div>`).join('')}<div class="trigger"><span class="trigger-icon">◉</span><div class="trigger-copy"><b>Weekly message limit</b><p>Keep messages thoughtful and never overwhelming</p></div><select class="select"><option>2 per week</option><option>1 per week</option><option>3 per week</option></select></div><div style="display:flex;gap:9px;margin-top:19px"><button class="btn btn-primary" onclick="runFollowup()">✧&nbsp; Run follow-up now</button><button class="btn btn-outline" onclick="simulateTime()">+1 month</button></div></article><article class="card"><div class="card-head"><div class="card-title">Recent check-ins</div><button class="text-link" onclick="go('Staff Inbox')">Open staff inbox →</button></div>${state.messages.slice().reverse().map(m=>`<div class="inbox-item"><span class="mini-avatar">${m.ai?'✦':'AO'}</span><div class="inbox-copy"><h4>${m.ai?'AI check-in sent':'Participant replied'} <span class="badge ${m.ai?'':'gray'}">${m.ai?'AI':'Received'}</span></h4><p>${esc(m.text)}</p><div class="case-meta">Amara Okafor · Today · Digital Skills for Work</div></div></div>`).join('')}<div class="spark"><b>✦ &nbsp; AI insight</b><br>Transport and busy work schedules are the most common reasons participants miss sessions this week.</div></article></section>`;}
function staffInbox(){const cases=state.cases.filter((_,i)=>!state.casesDone.includes(i));return `${head('YOUR TEAM, IN THE LOOP','Staff Inbox','A human touch when it matters. AI-handled replies stay visible for review.')}<div class="tabs"><button class="tab ${inboxTab==='Escalated'?'active':''}" onclick="setInboxTab('Escalated')">Needs attention <span class="badge red">${cases.length}</span></button><button class="tab ${inboxTab==='AI-resolved'?'active':''}" onclick="setInboxTab('AI-resolved')">AI-resolved <span class="badge">${state.casesDone.length+3}</span></button></div>${inboxTab==='Escalated'?cases.map((c,i)=>`<article class="card" style="margin-bottom:12px"><div class="card-head"><div style="display:flex;gap:10px;align-items:center"><span class="mini-avatar">${c.initials}</span><div><div class="card-title">${c.name}</div><div class="row-meta">Digital Skills for Work · Yoruba · 12 minutes ago</div></div></div><span class="badge ${c.urgency==='Critical'?'red':'orange'}">${c.urgency}</span></div><div class="grid split"><div><div class="eyebrow">ORIGINAL MESSAGE</div><p style="font-size:12px;margin:8px 0">“${c.message}”</p><div class="notice" style="margin:9px 0"><b>English meaning · AI translation</b><br>${c.translation}</div><div class="row-meta">Category · ${c.category.replaceAll('_',' ')}</div><div class="spark"><b>AI summary</b><br>${c.summary}</div></div><div><div class="field"><label>Suggested reply · AI</label><textarea id="reply-${i}" rows="4">${c.reply}</textarea></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-primary btn-small" onclick="replyCase(${i})">Send reply</button><button class="btn btn-soft btn-small" onclick="closeCase(${i})">Close case</button><button class="btn btn-outline btn-small" onclick="wrongCase(${i})">AI was wrong</button></div></div></div></article>`).join('')||'<div class="card empty">All caught up. Your team has no open escalations.</div>':`<article class="card"><div class="card-head"><div class="card-title">Handled by Voxera AI</div><span class="badge">Ready for review</span></div><div class="notice">These routine cases were resolved using pre-written language templates. You can review them at any time.</div>${[['Ngozi Eze','sick','Participant said they were unwell and will return next session.'],['Kemi Afolayan','will_watch_recording','Participant plans to catch up with the session recording.'],['Musa Ibrahim','transport','Participant mentioned a transport delay; acknowledged and logged.']].map(x=>`<div class="inbox-item"><span class="mini-avatar">✦</span><div class="inbox-copy"><h4>${x[0]} <span class="badge">AI-resolved</span></h4><p>${x[2]}</p><div class="case-meta">Category · ${x[1]} · Reviewed by AI</div></div><button class="btn btn-outline btn-small" onclick="toast('Case detail opened')">Review</button></div>`).join('')}</article>`}`;}
function messages(){return `${head('IN-HOUSE MESSAGING','Messages','Conversations stay here, with your team and the people in your programmes.')}<section class="grid split"><article class="card"><div class="card-head"><div class="card-title">Inbox</div><span class="badge">3 unread</span></div>${[['AO','Amara Okafor','I no get money for transport this week.','10:42 AM'],['TB','Tunde Bakare','Please, I need to talk to person.','Yesterday'],['NE','Ngozi Eze','Thank you, I will watch the recording.','Mon']].map(x=>`<div class="programme-row"><span class="mini-avatar">${x[0]}</span><div class="row-main"><div class="row-title">${x[1]}</div><div class="row-meta">${x[2]}</div></div><span class="row-meta">${x[3]}</span></div>`).join('')}</article><article class="card"><div class="card-head"><div class="card-title">Amara Okafor</div><span class="badge">Direct · In-house</span></div><div class="messages">${state.messages.map(m=>`<div class="msg ${m.ai?'ai':''} ${m.mine?'mine':''}">${esc(m.text)}<span class="msg-time">${m.time||'Just now'}</span></div>`).join('')}</div><div class="composer"><input id="message-input" placeholder="Write a thoughtful reply…" onkeydown="if(event.key==='Enter')sendMessage()"><button class="btn btn-primary" onclick="sendMessage()">Send</button></div></article></section>`;}
function reports(){return `${head('SEE THE DIFFERENCE','Reports','A clear picture of reach, attendance and the outcomes that matter.','<button class="btn btn-outline" onclick="downloadCsv()">↓&nbsp; Export CSV</button>')}<div class="toolbar"><select class="select"><option>All programmes</option>${state.programmes.map(p=>`<option>${p.title}</option>`).join('')}</select><select class="select"><option>Last 30 days</option><option>This quarter</option></select></div><section class="grid stats">${stat('Participants reached','148','Across 3 programmes','♙')}${stat('Completion rate','72%','↑ 8% from last quarter','✧')}${stat('Follow-up response','64%','↑ 11% this month','↩')}${stat('Certificates issued','36','18 more in progress','▧')}</section><section class="grid split"><article class="card"><div class="card-head"><div class="card-title">Attendance by session</div><span class="badge">All modes</span></div><div class="chart">${[63,72,59,84,68,77,92].map((v,i)=>`<div class="bar-wrap"><div class="bar ${i===6?'current':''}" style="height:${v}%"></div></div>`).join('')}</div><div class="chart-labels"><span>1</span><span>2</span><span>3</span><span>4</span><span>5</span><span>6</span><span>7</span></div></article><article class="card"><div class="card-head"><div class="card-title">How people attended</div></div>${[['Live online',58,'#1d493d'],['Recorded',27,'#94b884'],['In person',15,'#d9c88a']].map(x=>`<div class="progress-row"><span>${x[0]}</span><b>${x[1]}%</b></div><div class="progress" style="margin-bottom:15px"><i style="width:${x[1]}%;background:${x[2]}"></i></div>`).join('')}</article></section><article class="card" style="margin-top:16px"><div class="card-head"><div class="card-title">Common reasons for missed sessions</div><span class="badge">From follow-up</span></div>${[['Transport','38%'],['Work schedule','29%'],['Family commitments','18%'],['Health','15%']].map(x=>`<div class="progress-row"><span>${x[0]}</span><b>${x[1]}</b></div><div class="progress" style="margin-bottom:13px"><i style="width:${x[1]};background:#aac18e"></i></div>`).join('')}</article>`;}
function settings(){return `${head('YOUR WORKSPACE','Settings','Set up Voxera around your organisation and the people you serve.')}<section class="grid split"><article class="card"><div class="card-head"><div class="card-title">Organisation</div><button class="text-link" onclick="toast('Organisation details saved')">Save changes</button></div><div class="field"><label>Organisation name</label><input value="Bright Futures Initiative"></div><div class="field"><label>Organisation type</label><select><option>NGO</option><option>LGA</option><option>Company</option></select></div><div class="field"><label>Primary language</label><select><option>English</option><option>Nigerian Pidgin</option></select></div></article><article class="card"><div class="card-head"><div class="card-title">Privacy & consent</div><span class="badge">Participant controls</span></div>${[['Voice storage','Store participant audio only when they consent.'],['AI follow-up','Respect each participant’s follow-up preference.'],['Data use','Use information only to run and improve programmes.'],['Local data','Demo records stay on this device.']].map((x,i)=>`<div class="profile-option"><div><b>${x[0]}</b><div class="row-meta" style="margin-top:4px">${x[1]}</div></div><input class="switch" type="checkbox" ${i===3?'checked disabled':'checked'}></div>`).join('')}<div style="margin-top:18px"><button class="btn btn-outline" onclick="openModal('reset')">Reset demo data</button></div></article></section>`;}
function organizerPage(){return ({Dashboard:dashboard,Programmes:programmes,Participants:participants,Attendance:attendance,'Live Class':liveClass,'Follow-Up':messages,'Staff Inbox':messages,Messages:messages,Reports:reports,Settings:settings}[page]||dashboard)();}

function participant(){const sub=page;const navigation=[['Home','Home'],['Discover','Discover'],['Speak','mic'],['Messages','Messages'],['Profile','Profile']];return `<div class="phone-shell"><div class="phone-top"><a class="brand"><span class="brandmark">v</span> voxera</a><button type="button" class="avatar participant-self-avatar" aria-label="Open your profile" onclick="go('Profile')">${esc(currentUser?.name?.split(/\s+/).map(part=>part[0]).join('').slice(0,2)||'')}</button></div><div class="phone-content">${sub==='Home'?participantHome():sub==='Discover'?participantDiscover():sub==='My Programmes'?myProgrammes():sub==='Messages'?participantMessages():sub==='Profile'?profile():voicePage()}</div><nav class="phone-nav" aria-label="Participant navigation">${navigation.map(([label,key])=>`<button type="button" class="${page===label?'active':''} ${label==='Speak'?'mic':''}" aria-label="${label}" onclick="go('${label}')"><span class="nav-icon">${key==='mic'?lucideIcon('mic',19):icon[key]}</span><span class="phone-nav-label">${label==='Speak'?'':label}</span></button>`).join('')}</nav></div>`;}
function participantHome(){const selected=state.programmes[0];return `<div class="hello">MONDAY, 05 OCTOBER</div><h1 class="phone-title">Good morning,<br>Amara 🌿</h1><div class="phone-hero"><div class="eyebrow">YOUR NEXT STEP</div><h2>A little progress goes a long way.</h2><p>Your Digital Skills session is coming up soon.</p><button class="btn btn-lime btn-small" onclick="go('My Programmes')">View my Programme →</button></div><div class="phone-section-title">My Programmes <button class="text-link" style="float:right" onclick="go('My Programmes')">See all →</button></div><div class="phone-card">${progRow(selected,'Session 3 · Portfolio clinic','Enrolled')}<div class="phone-progress"><div class="progress-row"><span>Your attendance</span><b>68%</b></div><div class="progress lime"><i style="width:68%"></i></div><div class="row-meta" style="margin-top:8px">You’re close to your 70% certificate goal ✨</div></div></div>${state.approved?`<div class="phone-card">${progRow(state.programmes[0],'Your application is approved','Enrolled')}</div>`:''}<div class="phone-section-title">Coming up</div><div class="phone-card">${sessionRow('08','Portfolio clinic','Online · 10:00 AM')}</div><div class="phone-section-title">A little nudge</div><div class="phone-card" style="display:flex;gap:11px;align-items:center"><span class="programme-art orange">▷</span><div><div class="row-title">Your session recording is ready</div><div class="row-meta">Watch by Friday to stay on track</div></div></div><div class="phone-section-title">Need a hand?</div><button class="btn btn-soft" style="width:100%;padding:15px" onclick="go('Speak')">◉ &nbsp; Speak to Voxera</button>`;}
function participantDiscover(){return `<div class="hello">A NEW OPPORTUNITY</div><h1 class="phone-title">Find your next step</h1><input class="search" style="width:100%;margin-bottom:13px" placeholder="⌕  Search programmes"><div class="phone-chips">${['All','Skills','Health','Enterprise'].map(x=>`<button>${x}</button>`).join('')}</div><div class="phone-section-title">Made for you</div>${state.programmes.map((p,i)=>`<div class="phone-card"><div class="programme-cover ${p.cover}" style="height:86px;border-radius:10px;margin-bottom:13px"><span class="cover-icon" style="font-size:42px">${p.art}</span><span class="cover-tag">${p.category}</span></div><div class="row-title">${p.title}</div><div class="row-meta" style="margin:5px 0 11px">${p.format} · ${p.location}</div><p class="row-meta" style="line-height:1.6">${p.desc}</p><div class="program-foot"><span>${p.status==='Full'?'Waitlist open':p.spots+' spaces left'}</span><button class="btn btn-small ${p.status==='Full'?'btn-soft':'btn-primary'}" onclick="apply(${p.id})">${state.applied.includes(p.id)?'Applied':p.status==='Full'?'Join waitlist':'Apply'}</button></div></div>`).join('')}`;}
function myProgrammes(){return `<div class="hello">YOUR LEARNING JOURNEY</div><h1 class="phone-title">My Programmes</h1><div class="phone-card">${progRow(state.programmes[0],'Online · 6 sessions','In progress')}<div class="phone-progress"><div class="progress-row"><span>Attendance</span><b>${state.attended?'72':'68'}%</b></div><div class="progress lime"><i style="width:${state.attended?'72':'68'}%"></i></div></div></div><div class="phone-section-title">Sessions</div>${[['08','Portfolio clinic','Live online · 10:00 AM','Upcoming'],['01','Digital confidence','Recording · Due Friday','Watch recording'],['24','Getting started','Attended · Live online','Attended'],['17','Everyday tools','Missed · Follow-up sent','Missed']].map((s,i)=>`<div class="phone-card">${sessionRow(s[0],s[1],s[2])}${i===1?'<button class="btn btn-primary btn-small" onclick="watchRecording()">Watch recording →</button>':''}</div>`).join('')}<div class="phone-section-title">Physical check-in</div><div class="phone-card" style="text-align:center"><div class="row-title">Your participant QR</div><div class="qr"></div><div class="row-meta">Show this code to your Programme facilitator</div></div>${state.applied.map(id=>`<div class="phone-card">${progRow(state.programmes.find(p=>p.id===id),'Application received','Pending')}</div>`).join('')}`;}
function participantMessages(){return `<div class="hello">YOUR CONVERSATIONS</div><h1 class="phone-title">Messages</h1><div class="notice">🔒 &nbsp; Your messages stay inside Voxera.</div><div class="phone-card">${state.messages.map(m=>`<div class="msg ${m.ai?'ai':''} ${m.mine?'mine':''}" style="max-width:100%;margin-bottom:8px">${esc(m.text)}<span class="msg-time">${m.time||'Just now'}</span></div>`).join('')}<div class="composer"><input id="message-input" placeholder="Write a reply…" onkeydown="if(event.key==='Enter')sendMessage()"><button class="btn btn-primary btn-small" onclick="sendMessage()">Send</button></div><button class="btn btn-outline btn-small" style="margin-top:11px;width:100%" onclick="escalateHuman()">Talk to a person</button></div>`;}
function profile(){return `<div class="hello">YOUR SPACE</div><h1 class="phone-title">Profile</h1><div class="phone-card"><div class="profile-head"><div class="profile-big">${currentUser?.name?.split(' ').map(x=>x[0]).join('').slice(0,2)||'AO'}</div><div><div class="row-title" style="font-size:14px">${esc(currentUser?.name||'Amara Okafor')}</div><div class="row-meta">${esc(currentUser?.area||'Lagos')} · Voxera participant</div></div></div></div><div class="phone-section-title">Preferences</div><div class="phone-card"><div class="profile-option"><span>Preferred language</span><select class="select" id="language-select" onchange="savePreferences()"><option ${currentUser?.language==='English'?'selected':''}>English</option><option ${currentUser?.language==='Pidgin'?'selected':''}>Pidgin</option><option ${currentUser?.language==='Yoruba'?'selected':''}>Yoruba</option><option ${currentUser?.language==='Hausa'?'selected':''}>Hausa</option><option ${currentUser?.language==='Igbo'?'selected':''}>Igbo</option></select></div><div class="profile-option"><span>Voice recording storage</span><input id="consent-voice" class="switch" type="checkbox" onchange="saveConsent()"></div><div class="profile-option"><span>Programme follow-up</span><input id="consent-followup" class="switch" type="checkbox" checked onchange="saveConsent()"></div><div class="profile-option"><span>How we use your data</span><span class="badge">Your choice</span></div></div><div class="phone-section-title">My certificates</div><div id="certificate-list" class="cert"><div class="cert-mark">✧</div><h3>Your certificates will appear here</h3><p>Complete a Programme to earn your first certificate.</p></div><div class="phone-section-title">Your participant code</div><div class="phone-card" style="text-align:center"><div class="qr"></div><div class="row-meta">Show this at in-person sessions</div></div>`;}
function voicePage(){return `<div class="voice-panel"><div class="eyebrow">A VOICE THAT’S HEARD</div><h2>What can we help with?</h2><p>Speak in English, Pidgin, Yoruba, Hausa or Igbo. We’ll show you what we understood before anything happens.</p><div class="voice-orb">${state.recording?'◼':'🎙'}</div><button class="btn btn-primary" onclick="recordVoice()">${state.recording?'Stop recording':'Tap to speak'}</button><button class="btn btn-outline" style="margin-left:7px" onclick="openModal('type-message')">Type instead</button><div class="voice-status">${state.voiceText?'Transcript ready to review':'Your microphone stays on this device until you choose to send.'}</div>${state.voiceText?`<div class="phone-card" style="text-align:left"><div class="eyebrow">WHAT I HEARD · YORUBA</div><textarea id="voice-edit" style="width:100%;margin:10px 0;border:1px solid var(--line);border-radius:9px;padding:10px;min-height:55px">${esc(state.voiceText)}</textarea><div class="notice"><b>English meaning · AI translation</b><br>${esc(state.voiceText==='Mo fẹ́ forúkọ sílẹ̀ fún ẹ̀kọ́ iṣẹ́ ọnà'?'I want to register for the skills programme.':'I heard you want help with your Programme.')}</div><div style="display:flex;gap:7px"><button class="btn btn-primary btn-small" onclick="confirmVoice()">Confirm</button><button class="btn btn-outline btn-small" onclick="editVoice()">Edit text</button><button class="btn btn-soft btn-small" onclick="recordAgain()">Record again</button></div><div class="row-meta" style="margin-top:10px">✦ AI understood this message · Please check before continuing</div></div>`:''}</div>`;}
function render(){document.getElementById('app').innerHTML=authToken?layout(role==='participant'?participant():organizerPage()):loginPage();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});}

function go(next){if(next==='Staff Inbox'){window.setOrganisationMessagesTab?.('attention');next='Messages';}if(next==='Messages'&&page!=='Messages')window.prepareMessageInbox?.();page=next;render();window.scrollTo(0,0);if(next==='Messages')window.markActiveConversationRead?.();if(['Home','Discover','My Programmes'].includes(next))window.syncParticipantProgrammeData?.();}
function setProgrammeFilter(f){programmeFilter=f;render();}
function filterSearch(q){document.querySelectorAll('.programme-card').forEach(card=>card.style.display=card.innerText.toLowerCase().includes(q.toLowerCase())?'':'none');}
function searchPeople(q){document.querySelectorAll('#people-table tbody tr').forEach(row=>row.style.display=row.innerText.toLowerCase().includes(q.toLowerCase())?'':'none');}
async function apply(id){const p=state.programmes.find(x=>x.id===id);try{const result=await api(`/api/programmes/${id}/apply`,{method:'POST'});await hydrate();toast(result.message);}catch(error){toast(error.message);}render();}
function toggleLive(){state.live=!state.live;save();render();toast(state.live?'Live session started. Participants can join now.':'Session ended. Recording is ready to attach.');}
async function markAttendance(){try{await api('/api/sessions/1/attendance?participant_id=2&mode=physical_qr',{method:'POST'});state.attended=true;toast('Amara Okafor marked present. Attendance saved.');}catch(error){toast(error.message);}render();}
function watchRecording(){state.attended=true;save();openModal('recording');}
async function runFollowup(){if(!state.followup){toast('Follow-up is paused in Settings.');return;}try{const result=await api('/api/followup/run',{method:'POST'});await hydrate();toast(`Follow-up sent to ${result.sent} participants who opted in.`);}catch(error){toast(error.message);}render();}
async function simulateTime(){try{const result=await api('/api/demo/advance',{method:'POST',body:JSON.stringify({days:30})});state.days=result.offset_days;toast('Time moved forward one month. Post-programme check-ins are ready.');}catch(error){toast(error.message);}}
function setInboxTab(v){inboxTab=v;render();}
async function replyCase(i){const c=state.cases.filter((_,j)=>!state.casesDone.includes(j))[i];if(!c)return;const value=$(`#reply-${i}`)?.value||c.reply;try{await api(`/api/cases/${c.id}/reply`,{method:'POST',body:JSON.stringify({body:value})});await hydrate();toast('Reply sent. Case marked handled by staff.');}catch(error){toast(error.message);}render();}
async function closeCase(i){const c=state.cases.filter((_,j)=>!state.casesDone.includes(j))[i];if(c)try{await api(`/api/cases/${c.id}/close`,{method:'PATCH'});await hydrate();toast('Case closed and added to the audit log.');}catch(error){toast(error.message);}render();}
function wrongCase(i){toast('Feedback recorded. This case is marked for AI review.');}
async function sendMessage(){const input=$('#message-input');if(!input||!input.value.trim())return;try{if(!conversationId){await hydrate();}if(!conversationId)throw new Error('No conversation is available yet.');await api(`/api/conversations/${conversationId}/messages`,{method:'POST',body:JSON.stringify({body:input.value.trim(),language:currentUser?.language||'English'})});await hydrate();render();}catch(error){toast(error.message);}}
async function escalateHuman(){try{await api('/api/cases/from-reply',{method:'POST',body:JSON.stringify({text:'I would like to speak to a person.',language:currentUser?.language||'English',confirmed:true})});await hydrate();toast('A team member has been notified.');go('Messages');}catch(error){toast(error.message);}}
function recordVoice(){if(state.recording){state.recording=false;state.voiceText='Mo fẹ́ forúkọ sílẹ̀ fún ẹ̀kọ́ iṣẹ́ ọnà';save();render();return;}if(!navigator.mediaDevices?.getUserMedia){state.voiceText='Mo fẹ́ forúkọ sílẹ̀ fún ẹ̀kọ́ iṣẹ́ ọnà';save();render();toast('Demo transcript loaded. Microphone requires HTTPS or localhost.');return;}state.recording=true;render();navigator.mediaDevices.getUserMedia({audio:true}).then(stream=>{const recorder=new MediaRecorder(stream);let chunks=[];recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());state.recording=false;state.voiceText='Mo fẹ́ forúkọ sílẹ̀ fún ẹ̀kọ́ iṣẹ́ ọnà';save();render();};recorder.start();setTimeout(()=>{if(recorder.state==='recording')recorder.stop();},4500);}).catch(()=>{state.recording=false;state.voiceText='Mo fẹ́ forúkọ sílẹ̀ fún ẹ̀kọ́ iṣẹ́ ọnà';save();render();toast('Microphone unavailable. You can type instead.');});}
async function confirmVoice(){const edit=$('#voice-edit');if(edit)state.voiceText=edit.value;try{state.voiceResult=await api('/api/voice/confirm',{method:'POST',body:JSON.stringify({text:state.voiceText,language:currentUser?.language||'Yoruba',confirmed:true})});toast('Thanks — we checked what you said.');}catch(error){toast(error.message);}openModal('voice-confirmed');}
function editVoice(){const edit=$('#voice-edit');if(edit){edit.focus();toast('Edit your transcript above, then confirm.');}}
function recordAgain(){state.voiceText='';save();render();recordVoice();}
async function downloadCsv(){try{const response=await fetch('/api/reports.csv',{headers:{Authorization:`Bearer ${authToken}`}});if(!response.ok)throw new Error('Your account cannot export this report.');const blob=await response.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='voxera-report.csv';a.click();URL.revokeObjectURL(a.href);toast('Your report is ready.');}catch(error){toast(error.message);}}
function editProgramme(id){toast(`Opening ${state.programmes.find(p=>p.id===id).title} details`);}
function openModal(type){let inner='';if(type==='new-programme')inner=`<h2>Create a Programme</h2><p>Start with the essentials. You can add sessions and participants next.</p><div class="field"><label>Programme name</label><input id="new-title" placeholder="e.g. Digital Skills for Work"></div><div class="field"><label>Format</label><select id="new-format"><option>Online</option><option>Physical</option><option>Hybrid</option></select></div><div class="field"><label>Short description</label><textarea id="new-desc" rows="3" placeholder="What will participants learn?"></textarea></div><div class="modal-actions"><button class="btn btn-outline" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="createProgramme()">Create Programme</button></div>`;
else if(type==='qr')inner=`<h2>Physical attendance</h2><p>Choose how you’d like to check participants in today.</p><div class="tabs"><button class="tab active">Scan participant</button><button class="tab" onclick="toast('Session QR code generated')">Show session QR</button></div><div class="notice">Camera scanning needs HTTPS. For this demo, you can mark participants present from the attendance grid.</div><div class="qr"></div><div class="modal-actions"><button class="btn btn-outline" onclick="closeModal()">Close</button><button class="btn btn-primary" onclick="markAttendance();closeModal()">Mark participant present</button></div>`;
else if(type==='recording')inner=`<h2>Recording player</h2><p>Skipping ahead does not count. Your progress is saved on this device.</p><div class="live-stage" style="min-height:190px"><div class="live-center"><button class="play" onclick="this.innerText=this.innerText==='▶'?'Ⅱ':'▶'">▶</button><h3>Digital confidence · Session 1</h3><p>Watched 72% · 18 minutes remaining</p></div></div><div class="progress-row"><span>Progress toward attendance</span><b>72%</b></div><div class="progress lime"><i style="width:72%"></i></div><div class="notice" style="margin-top:14px">✓ 70% reached. The session quiz is unlocked. Complete it before Friday to receive attendance credit.</div><div class="modal-actions"><button class="btn btn-outline" onclick="closeModal()">Save and exit</button><button class="btn btn-primary" onclick="toast('Quiz unlocked — 3 questions ready');closeModal()">Continue to quiz</button></div>`;
else if(type==='type-message')inner=`<h2>Type your message</h2><p>We’ll show you what Voxera understood before we take action.</p><div class="field"><label>Your message</label><textarea id="typed-voice" rows="4" placeholder="Ask about a Programme, explain an absence, or request a person"></textarea></div><div class="modal-actions"><button class="btn btn-outline" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="typedMessage()">Review message</button></div>`;
else if(type==='voice-confirmed')inner=`<h2>Message confirmed</h2><p>Your transcript is ready. In a fully connected setup, local AI would classify this with your consent and programme data.</p><div class="notice"><b>AI understood:</b><br>${esc(state.voiceText)}<br><br><b>Possible intent:</b> Ask about or register for a Programme.</div><div class="modal-actions"><button class="btn btn-outline" onclick="closeModal()">Close</button><button class="btn btn-primary" onclick="closeModal();go('Discover')">Explore Programmes</button></div>`;
else if(type==='reset')inner=`<h2>Reset demo data?</h2><p>This clears changes saved on this device and restores the original demo workspace.</p><div class="modal-actions"><button class="btn btn-outline" onclick="closeModal()">Keep my changes</button><button class="btn btn-primary" onclick="resetDemo()">Reset demo</button></div>`;
else inner=`<h2>Voxera demo</h2><p>Programme tools are running locally in this browser. Switch between organiser and participant views from the top right.</p><div class="modal-actions"><button class="btn btn-primary" onclick="closeModal()">Got it</button></div>`;
document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-top"><div>${inner}</div><button class="close" onclick="closeModal()">×</button></div></div></div>`);}
function closeModal(){$('.modal-back')?.remove();}
async function createProgramme(){const title=$('#new-title')?.value.trim();if(!title){toast('Add a Programme name to continue.');return;}try{await api('/api/programmes',{method:'POST',body:JSON.stringify({title,description:$('#new-desc').value||'A new learning opportunity for your community.',format:$('#new-format').value,category:'Skills & employment',location:'Lagos',capacity:20,start_date:'2026-10-12',end_date:'2026-11-23'})});await hydrate();closeModal();render();toast('Programme created with six sessions.');}catch(error){toast(error.message);}}
function typedMessage(){const text=$('#typed-voice')?.value.trim();if(!text){toast('Type a message first.');return;}state.voiceText=text;save();closeModal();render();}
async function resetDemo(){try{await api('/api/demo/reset',{method:'POST'});localStorage.removeItem('voxera-demo');state=structuredClone(seed);await hydrate();closeModal();render();toast('Demo reset. You’re ready to rehearse again.');}catch(error){toast(error.message);}}
async function saveConsent(){try{await api('/api/profile/consent',{method:'PATCH',body:JSON.stringify({data:true,voice_storage:$('#consent-voice')?.checked||false,followup:$('#consent-followup')?.checked||false,remote_ai:$('#consent-remote-ai')?.checked||false})});state.profile=await api('/api/profile');toast('Your consent preferences are saved.');}catch(error){toast(error.message);}}
async function savePreferences(){const language=$('#language-select')?.value;if(!language)return;try{currentUser=await api('/api/profile/preferences',{method:'PATCH',body:JSON.stringify({language})});toast('Language preference saved.');}catch(error){toast(error.message);}}
async function bootstrap(){try{currentUser=await api('/api/auth/me');role=currentUser.role;if(role==='admin'&&!currentUser.is_platform_owner)throw new Error('Legacy administrator access is disabled.');page=role==='admin'?'Overview':role==='participant'?'Home':'Dashboard';localStorage.setItem('voxera-role',role);await hydrate();if(role==='admin')state.ownerOverview=await api('/api/admin/overview');render();}catch{authToken='';currentUser=null;localStorage.removeItem('voxera-token');localStorage.removeItem('voxera-role');render();}}
window.go=go;window.setRole=setRole;window.loginDemo=loginDemo;window.loginForm=loginForm;window.logout=logout;window.apply=apply;window.toggleLive=toggleLive;window.markAttendance=markAttendance;window.watchRecording=watchRecording;window.runFollowup=runFollowup;window.simulateTime=simulateTime;window.setInboxTab=setInboxTab;window.replyCase=replyCase;window.closeCase=closeCase;window.wrongCase=wrongCase;window.sendMessage=sendMessage;window.escalateHuman=escalateHuman;window.recordVoice=recordVoice;window.confirmVoice=confirmVoice;window.editVoice=editVoice;window.recordAgain=recordAgain;window.downloadCsv=downloadCsv;window.openModal=openModal;window.closeModal=closeModal;window.createProgramme=createProgramme;window.typedMessage=typedMessage;window.resetDemo=resetDemo;window.editProgramme=editProgramme;window.setProgrammeFilter=setProgrammeFilter;window.filterSearch=filterSearch;window.searchPeople=searchPeople;window.saveConsent=saveConsent;window.savePreferences=savePreferences;
if(authToken)bootstrap();else render();
